// Original Stepstone value diagrams, generated by tools/build_teaching_money.py.
// Currency portraits, logos and engraved designs are not reproduced.
// The Museum is linked as a real-cash learning resource, not as the art source.
export const MONEY_SOURCE='https://www.bankofcanadamuseum.ca/2020/11/printable-play-money/';
const TEN="./money/cad-10-value119.svg";
const LOONIE="./money/cad-loonie-value119.svg";
const QUARTER="./money/cad-quarter-value119.svg";
export function canadianTen(x,y,width=75,height=150){
  return `<image data-cad="10-dollars" x="${x}" y="${y}" width="${width}" height="${height}" preserveAspectRatio="xMidYMid meet" href="${TEN}"/>`;
}
export function canadianCoin(value,x,y,size=50){
  if(![1,.25].includes(value))throw new RangeError('Unsupported Canadian teaching coin');
  const key=`cad-coin-${value}-${x}-${y}`,r=size/2;
  return `<defs><clipPath id="${key}"><circle cx="${x+r}" cy="${y+r}" r="${r}"/></clipPath></defs><image data-cad="${value===1?'1-dollar':'25-cents'}" x="${x}" y="${y}" width="${size}" height="${size}" preserveAspectRatio="xMidYMid meet" clip-path="url(#${key})" href="${value===1?LOONIE:QUARTER}"/>`;
}
export function moneyCredit(){return `<p class="money-source">Original value diagrams by Stepstone. Recognise real Canadian cash with the <a href="${MONEY_SOURCE}" target="_blank" rel="noopener noreferrer">Bank of Canada Museum</a> teaching resource.</p>`;}

const CASH_ART={500:['cad-5-value119.svg','Canadian five-dollar value diagram ($5)'],200:['cad-toonie-value119.svg','Canadian two-dollar value diagram (toonie)'],100:['cad-loonie-value119.svg','Canadian one-dollar value diagram (loonie)'],25:['cad-quarter-value119.svg','Canadian 25-cent value diagram (quarter)']};
export function canadianMoneyPiece(cents){
  const piece=CASH_ART[cents];if(!piece)throw new RangeError('Unsupported Canadian cash denomination');
  return `<img class="money-art ${cents>=500?'money-note':'money-coin'}" src="./money/${piece[0]}" alt="${piece[1]}" draggable="false" width="${cents>=500?130:72}" height="72">`;
}
export function lessonSourceFooter(unit,resources=''){
  const museum=['math-2','math-cash'].includes(unit.id)?moneyCredit():'';
  return resources||museum?`<footer class="lesson-sources" aria-label="Lesson sources">${resources}${museum}</footer>`:'';
}
